using DomainModel.Context; using Microsoft.EntityFrameworkCore; namespace DataAccess.Repositories.SiteSetting; public class SiteSettingRepository(ApplicationDbContext c):ISiteSettingRepository { public Task<DomainModel.Models.SiteSetting?> GetAsync(bool tracking=true)=>(tracking?c.SiteSettings:c.SiteSettings.AsNoTracking()).OrderBy(x=>x.SiteSettingID).FirstOrDefaultAsync(); public Task AddAsync(DomainModel.Models.SiteSetting s)=>c.SiteSettings.AddAsync(s).AsTask(); public Task<int> SaveChangesAsync()=>c.SaveChangesAsync(); }
